            assert_eq!(results.len(), count);
            let actual = sqlx::query!(
                "SELECT current_setting('pg_trgm.word_similarity_threshold') AS threshold"
            )
            .fetch_one(&pool)
            .await?
            .threshold;
            assert_eq!(actual, initial);
        }
        Ok(())
    }
