    /// This function expects the repositories to return their results
    /// in order where a higher score means a higher similarity.
    async fn search_entities(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<Entity>, EntitySearchError> {
        let mps = self.mp_repo.get_members_by_text_search_score(req).await?;
        let funders = self
            .funder_repo
            .get_funders_by_text_search_score(req)
            .await?;

        let mut results = merge_scores(&mps, &funders.matches);
        if mps.is_empty() && !funders.has_qualifying_individual {
            let fallback_mps = self.mp_repo.get_members_by_phonetic_search(req).await?;
            let fallback_funders = self.funder_repo.get_funders_by_phonetic_search(req).await?;
            let remaining = usize::from(req.max_entries()).saturating_sub(funders.matches.len());
            let mut fallback: Vec<_> = fallback_mps
                .into_iter()
                .map(|(mp, rank)| (Entity::ParliamentMember(mp), rank))
                .chain(
                    fallback_funders
                        .into_iter()
                        .filter(|(funder, _)| {
                            !funders
                                .matches
                                .iter()
                                .any(|(primary, _)| primary.funder().id() == funder.funder().id())
                        })
                        .take(remaining)
                        .map(|(funder, rank)| (Entity::Funder(funder), rank)),
                )
                .collect();
            fallback.sort_by(|(left, a), (right, b)| {
                a.compare(b).then_with(|| match (left, right) {
                    (Entity::ParliamentMember(a), Entity::ParliamentMember(b)) => {
                        a.member_id().value().cmp(&b.member_id().value())
                    }
                    (Entity::Funder(a), Entity::Funder(b)) => {
                        a.funder().id().value().cmp(&b.funder().id().value())
                    }
                    (Entity::ParliamentMember(_), Entity::Funder(_)) => std::cmp::Ordering::Less,
                    (Entity::Funder(_), Entity::ParliamentMember(_)) => std::cmp::Ordering::Greater,
                })
            });
            results.extend(fallback.into_iter().map(|(entity, _)| entity));
        }
        Ok(results)
    }
}

/// Uses two-pointer technique to merge to pre-sorted
/// search results together.
fn merge_scores(
    mps: &[(ParliamentMember, SearchSimilarity)],
    funders: &[(FunderSearchMatch, SearchSimilarity)],
) -> Vec<Entity> {
    let mut scores = Vec::new();

    let (mut l, mut r) = (0, 0);
    // Unwrap acceptable as index check in
    // while function
    while l < mps.len() && r < funders.len() {
        let mp: &(ParliamentMember, SearchSimilarity) = mps.get(l).unwrap();
        let fund: &(FunderSearchMatch, SearchSimilarity) = funders.get(r).unwrap();

        match &mp.1.value().total_cmp(&fund.1.value()) {
            std::cmp::Ordering::Equal => {
                scores.push(Entity::from(&mp.0));
                scores.push(Entity::from(&fund.0));
                l += 1;
            word_similarity_candidate_threshold(req.strictness())
        )
        .fetch_one(&mut *tx)
        .await
        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        let rows = sqlx::query!(
            "
            WITH candidates AS (
                SELECT id FROM exposed.funders WHERE funder_name %> $1
                UNION
                SELECT funder_id FROM exposed.funder_aliases WHERE funder_alias %> $1
            ), scored AS (
                SELECT f.id, f.funder_name AS name, f.funder_kind AS kind,
                    word_similarity($1, f.funder_name) AS canonical_score,
                    a.funder_alias, a.alias_score
                FROM candidates c
                JOIN exposed.funders f ON f.id = c.id
                LEFT JOIN LATERAL (
                    SELECT funder_alias, word_similarity($1, funder_alias) AS alias_score
                    FROM exposed.funder_aliases WHERE funder_id = f.id
                    ORDER BY alias_score DESC, funder_alias COLLATE \"C\" ASC
                    LIMIT 1
                ) a ON true
            )
            , qualified AS (
            SELECT id, name, kind,
                CASE WHEN alias_score > canonical_score THEN funder_alias END AS matched_alias,
                GREATEST(canonical_score, COALESCE(alias_score, 0)) AS similarity_score
            FROM scored
            WHERE GREATEST(canonical_score, COALESCE(alias_score, 0)) >= $2
            )
            SELECT *, EXISTS(SELECT FROM qualified WHERE kind = $4) AS \"has_individual!\"
            FROM qualified
            ORDER BY similarity_score DESC, id
            LIMIT $3
            ",
            req.term(),
            req.strictness(),
            i64::from(req.max_entries()),
            FunderKind::Individual.as_ref(),
        )
        .fetch_all(&mut *tx)
        .await
        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        tx.commit()
            .await
            .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        let has_qualifying_individual = rows.first().is_some_and(|row| row.has_individual);
        let matches = rows
            .into_iter()
            .map(|r| {
                let kind = r.kind.map_or(FunderKind::NotSpecified, |ref kind| {
                    FunderKind::from_str(kind).unwrap()
                });
                let funder = Funder::new(FunderId::new(r.id), r.name, kind);
                let score = SearchSimilarity::from(r.similarity_score.unwrap_or(0_f32));
                Ok((
                    FunderSearchMatch::new(
                        funder,
                        r.matched_alias.map_or(SearchMatchSource::Name, |name| {
                            SearchMatchSource::Alias { name }
                        }),
                    ),
                    score,
                ))
            })
            .collect::<Result<Vec<_>, FunderRepoError>>()?;
        Ok(FunderSearchResults {
            matches,
            has_qualifying_individual,
        })
    }
